/**
 * 提供猎魔人具体夜间生命周期、玩家投影及请求预检的公开入口；输入保留原 World、开启与终结引用。
 * 输出为实际夜间单元、原查询结果与原工具读取绑定。开启仍在原阶段，晚移交先于 pipeline 清理，
 * close／abort 保持经理与 pipeline 的原顺序；请求当前性、资源读写权限仍由具体权威所有者验证。
 * 单元拥有获取与移交，权威拥有规则；公开入口不新增作用域、包装状态、库存或编码政策。
 * 原生控制器 loader 仅在实际调用时返回原动态 import Promise，公开它们不提前初始化控制器。
 * 猎魔来源折叠先于夜仆收尾，事实发布在最终来源检查之后；公开窄查询不授予库存或死亡写权。
 */
export { DemonNightUnit, demonNightTerminal } from "./night-lifecycle";

/** 原引擎查询保持同一权威函数绑定与参数。 */
export {
  isRedMoonBoard,
  demonHunterActorId,
  demonRedMoonCanBlast,
  demonHunterNativeGunCurrent,
  openDemonHunterStockFrame,
  assertDemonNightReadable,
  originalDemonNightLives,
  demonOriginalWolfSourceCurrent,
  demonOriginalWolfTargetCurrent,
  demonRedMoonExpiry,
  commitDemonRedMoonTransition,
  committedDemonFaultBoundary,
  assertDemonOriginalRoster,
  hasDemonNightStarted,
  demonWitchRequiredThisNight,
} from "./authority";

/** 原生控制器保持原懒加载 import Promise，仅在实际使用时初始化。 */
export function loadDemonNativeNightController() {
  return import("./native_night_controller");
}

export function loadDemonNativePotionController() {
  return import("./native_potion_controller");
}

export { projectDemonHunter } from "./authority";

export { demonWitchRequestTargetCurrent } from "./native_potion_requests";

export { demonWitchRequestCurrent } from "./native_potion_requests";

export { readDemonNativeNightTool } from "./native_potion_requests";

export { readDemonPotionTool } from "./native_potion_requests";

/** 同一请求实现中的可信库存查询；保原模块捕获点与逐方法拒绝顺序，不授予库存写权。 */
export { demonWitchMarksSafe } from "./native_potion_requests";

export { demonHunterRequestScope } from "./authority";

export { canSubmitDemonHunt } from "./authority";

export { readDemonHuntTool } from "./state";

export {
  appendDemonNightDamageSources,
  publishDemonNightDamageSources,
  type DemonKnifeProtection,
  type DemonNightDamageQueries,
  type DemonNightDamagePublicationRuntime,
} from "./night-damage-contribution";

/**
 * 负责猎人的死亡钩子贡献，在原死亡波中装配枪击选择、死因政策与公开事件。
 * 输入是原 World 玩家、死亡原因、选择回调与当前生命上下文；输出是待提交的枪击死亡和猎人事件。
 * 可用枪击之前的死因、原生命和行动权限检查，以及接受之后的原生枪消费，均由共享枪击所有者负责。
 * 中毒保留原沉默事件，失败或关闭窗口不绕过检查。本钩子不打开死亡权限、不提交目标死亡，
 * 也不切换阶段或关闭死亡波。
 */
import { Role, permitsHunterShot } from "../../../../core/domain/model";
import type { DeathHook } from "../../hooks/hook_registry";
import { getHunterState } from "../native-death-gun-resources";
import { openDemonHunterStockFrame } from "../demon_hunter/ports";
import { resolveNativeDeathShots } from "../native-death-shot-settlement";

export const hunterDeathHook: DeathHook = (world, ids, sources, choose, events, context) =>
  resolveNativeDeathShots(
    world,
    ids,
    sources,
    choose,
    events,
    {
      role: Role.Hunter,
      state: getHunterState,
      // 仅实际 Hunter 分支晚取原命令；本 getter 不读 World，不提前捕获审计。
      get openHunterStock() { return openDemonHunterStockFrame; },
      permits: (sources) => permitsHunterShot(sources),
      policy: (state) => state.deathActionPolicy ?? "awa_qualified_sources_v1",
      poisonEvent: (hunterId) => ({
        timestamp: Date.now(),
        type: "hunter_silent_due_to_poison",
        payload: { hunterId },
      }),
      shotEvent: (hunterId, targetId) => ({
        timestamp: Date.now(),
        type: "hunter_shot",
        payload: { hunterId, targetId },
      }),
    },
    context,
  );

/**
 * 负责四族原生／学习死亡枪的数据创建、原槽安装、武装、捕获复验和库存消费。
 * 输入为原角色、原学习对象与晚取查询；输出保留同一槽／枪引用和原每次 hook 的捕获表。
 * 原生安装不克隆、不冻库存；学习模板仅创建自己的全新枪，已有整学习数据的复制仍由各族安装 owner 执行。
 * 本 owner 只写原枪字段，原体、生命、死因及请求许可仍在结算／具体权威复验；只读类型不是权限屏障。
 * 猎魔板子先捕获原审计库存，支付仍由同一权威执行；setter／编码或后续发表失败均不退款。
 */
import type {
  HunterState, HunterReadState, WolfKingState, WolfKingReadState,
  MechanicalReadState as MechanicalState, MechanicalReadLearning as MechanicalLearning,
  MechanicalReadSkill as MechanicalSkill, MechanicalReadState,
  AwakenedReadState as AwakenedState, AwakenedReadLearning as AwakenedLearning,
  AwakenedReadSkill as AwakenedSkill, AwakenedReadState,
} from "@ai-werewolf-arena/game-contract";
import { Camp, Role } from "../../../core/domain/model";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { World } from "../../../core/domain/world";
import type { RoleInitContext } from "./contracts";
import type { openDemonHunterStockFrame } from "./demon_hunter/ports";

/** 创建仍逐次读取原配置 getter，不缓存 boardConfig／policy；分支保持原字段可选性。 */
export function createHunterState(ctx: Pick<RoleInitContext, "boardConfig">): HunterState {
  return {
    canShoot: true,
    ...(ctx.boardConfig?.hunter?.deathActionPolicy === "awa_knife_or_exile_v1"
      ? { deathActionPolicy: ctx.boardConfig.hunter.deathActionPolicy }
      : {}),
  };
}
export function createWolfKingState(ctx: Pick<RoleInitContext, "boardConfig">): WolfKingState {
  return {
    canShoot: true,
    ...(ctx.boardConfig?.wolfKing?.deathActionPolicy !== undefined &&
    ctx.boardConfig.wolfKing.deathActionPolicy !== "awa_qualified_sources_v1"
      ? { deathActionPolicy: ctx.boardConfig.wolfKing.deathActionPolicy }
      : {}),
  };
}

/** get 仍可调用原槽 getter；set 原左值赋入同对象，不新增 schema 或 descriptor 拒绝。 */
export function setHunterState(roleComp: RoleComponent, state: HunterState): HunterReadState {
  (roleComp.privateState as { hunter: HunterState })["hunter"] = state;
  return state;
}

export function getHunterState(roleComp: RoleComponent): HunterReadState | undefined {
  return (roleComp.privateState as { readonly hunter?: unknown })["hunter"] as
    HunterReadState | undefined;
}

export function setWolfKingState(roleComp: RoleComponent, state: WolfKingState): WolfKingReadState {
  (roleComp.privateState as { wolf_king: WolfKingState })["wolf_king"] = state;
  return state;
}

export function getWolfKingState(roleComp: RoleComponent): WolfKingReadState | undefined {
  return (roleComp.privateState as { readonly wolf_king?: unknown })["wolf_king"] as
    WolfKingReadState | undefined;
}

export type LearnedNativeGun = Extract<MechanicalSkill, { kind: "hunter" }>;
/** 学习得到新满库存模板，不从目标玩家复制已花费资源或原体许可。 */
export function createLearnedNativeGun(): { kind: "hunter"; canShoot: boolean; armed: boolean } {
  return { kind: "hunter", canShoot: true, armed: false };
}
/** 实际夜／激活检查仍由本族调用方先完成；只在原赋值点武装同一枪，不补偿其他字段。 */
export function armLearnedNativeGun(gun: LearnedNativeGun): void {
  (gun as { armed: boolean }).armed = true;
}

/** 原每次 hook 私有的捕获表；不跨波、World 或角色复用，换学习／原枪后返回 undefined。 */
export function createMechanicalGunReader(runtime: { readonly getMechanicalState: (role: RoleComponent | undefined) => MechanicalReadState | undefined }): (role: RoleComponent) => LearnedNativeGun | undefined {
  const owners = new Map<
    RoleComponent,
    {
      state: MechanicalState;
      learning: MechanicalLearning;
      gun: Extract<MechanicalSkill, { kind: "hunter" }>;
    }
  >();
  return (role) => {
        const query = runtime.getMechanicalState;
        const state = query(role),
          learning = state?.learned,
          skill = learning?.skill;
        if (
          role.camp !== Camp.Wolf ||
          !state ||
          !learning ||
          skill?.kind !== "hunter" ||
          !skill.armed
        )
          return undefined;
        const prior = owners.get(role);
        if (prior && (state !== prior.state || learning !== prior.learning || skill !== prior.gun))
          return undefined;
        if (!prior) owners.set(role, { state, learning, gun: skill });
        return skill;
  };
}

/** 原每次 hook 私有的捕获表；不跨波、World 或角色复用，换学习／原枪后返回 undefined。 */
export function createAwakenedGunReader(runtime: { readonly getAwakenedState: (role: RoleComponent | undefined) => AwakenedReadState | undefined }): (role: RoleComponent) => LearnedNativeGun | undefined {
  const owners = new Map<
    RoleComponent,
    {
      state: AwakenedState;
      learned: AwakenedLearning;
      gun: Extract<AwakenedSkill, { kind: "hunter" }>;
      targetId: number;
      role: AwakenedLearning["role"];
      day: number;
      activationNight: number;
      activeFromNight: number;
    }
  >();
  return (role) => {
        const query = runtime.getAwakenedState;
        const state = query(role),
          learned = state?.learned,
          gun = learned?.skill;
        if (
          role.camp !== Camp.Wolf ||
          !state ||
          !learned ||
          learned.role !== Role.Hunter ||
          learned.activationNight === null ||
          learned.activeFromNight === null ||
          gun?.kind !== "hunter" ||
          !gun.armed
        )
          return undefined;
        const prior = owners.get(role);
        if (
          prior &&
          (state !== prior.state ||
            learned !== prior.learned ||
            gun !== prior.gun ||
            learned.targetId !== prior.targetId ||
            learned.role !== prior.role ||
            learned.day !== prior.day ||
            learned.activationNight !== prior.activationNight ||
            learned.activeFromNight !== prior.activeFromNight)
        )
          return undefined;
        if (!prior)
          owners.set(role, {
            state,
            learned,
            gun,
            targetId: learned.targetId,
            role: learned.role,
            day: learned.day,
            activationNight: learned.activationNight,
            activeFromNight: learned.activeFromNight,
          });
        return gun;
  };
}

/** 晚取原猎魔命令；非 Hunter 分支不读命令，类型引用不会初始化 authority。 */
export interface NativeDeathGunStockQueries {
  readonly openHunterStock?: typeof openDemonHunterStockFrame;
}
export function captureNativeGunStock(
  kind: Role,
  queries: NativeDeathGunStockQueries,
  world: World,
  actorId: number,
  state: object,
): ReturnType<typeof openDemonHunterStockFrame> {
  if (kind !== "hunter") return null;
  const command = queries.openHunterStock!;
  return command(world, actorId, state);
}
/** 付款不补资格：原 stock 自验并写审计；普通分支只写原 canShoot。失败保原写入前缀。 */
export function consumeNativeDeathGun(
  state: { readonly canShoot: boolean },
  stock: ReturnType<typeof openDemonHunterStockFrame>,
): void {
  if (stock) stock.consume();
  else (state as { canShoot: boolean }).canShoot = false;
}
